import React from 'react';
import {AbsoluteFill, Audio, Easing, Sequence, staticFile, useCurrentFrame} from 'remotion';
import {loadFont} from '@remotion/google-fonts/Inter';
import {loadFont as loadPoppins} from '@remotion/google-fonts/Poppins';
import content from './content.json';
import voTiming from './vo-timing.json';

// ---------------------------------------------------------------------------
// Editable text, data, colors and timing live in content.json (brand: DataEntropy
// guideline). vo-timing.json is generated by `npm run srt` from the voiceover.
// All motion is keyed to scene start frames, so moving a scene's `start`
// shifts its animations with it.
// ---------------------------------------------------------------------------

const {fontFamily} = loadFont('normal', {weights: ['400', '500', '600', '700'], subsets: ['latin']});
const FONT = `${fontFamily}, Arial, sans-serif`;
// The wordmark is set in a geometric sans (Poppins) to match the logo artwork.
const LOGO_FONT = `${loadPoppins('normal', {weights: ['700'], subsets: ['latin']}).fontFamily}, ${FONT}`;

const C = content.colors;
const FPS = content.fps;
const END = content.durationSeconds * FPS;
const S = content.scenes.map((s) => Math.round(s.start * FPS)); // scene start frames
const sceneEnd = (i: number) => (i + 1 < S.length ? S[i + 1] : END);

// Screen layout (brand safe area: 10% top, 18% bottom, 7% sides).
const SAFE = {left: 76, right: 1004};
const HEADLINE_Y = 250; // first headline baseline
const CONTENT_CY = 890; // screen y the camera centers content on (between headline and subtitles)
const SUB_BOTTOM = 1560;

// Easing: brand curve for things entering, ease-in-out for on-screen morphs,
// ease-in only for one-way exits, linear for time-based motion.
type Ease = (t: number) => number;
const EASE = {
	out: Easing.bezier(0.22, 1, 0.36, 1),
	inOut: Easing.bezier(0.645, 0.045, 0.355, 1),
	in: Easing.bezier(0.55, 0.055, 0.675, 0.19),
	linear: (t: number) => t,
};

// Keyframe track: kf(frame, [f0, f1, ...], [v0, v1, ...], easing), clamped.
// `easing` is one curve for all segments or an array with one per segment.
const kf = (f: number, frames: number[], values: number[], easing: Ease | Ease[] = EASE.inOut) => {
	if (f <= frames[0]) return values[0];
	const i = frames.findIndex((_, k) => k + 1 < frames.length && f < frames[k + 1]);
	if (i < 0) return values[values.length - 1];
	const e = Array.isArray(easing) ? easing[i] : easing;
	return values[i] + (values[i + 1] - values[i]) * e((f - frames[i]) / (frames[i + 1] - frames[i]));
};
const enter = (f: number, frames: number[], values: number[]) => kf(f, frames, values, EASE.out);
const clamp01 = (v: number) => Math.max(0, Math.min(1, v));

const mixColor = (a: string, b: string, t: number) => {
	const p = (h: string) => [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16));
	const [x, y] = [p(a), p(b)];
	return '#' + x.map((v, i) => Math.round(v + (y[i] - v) * t).toString(16).padStart(2, '0')).join('');
};

// "*word*" marks a highlighted word. Returns words with their highlight flag.
const parseMarked = (s: string) =>
	s.split(/(\*[^*]+\*)/).flatMap((part) => {
		const hl = part.startsWith('*');
		return part.replaceAll('*', '').split(/\s+/).filter(Boolean).map((w) => ({w, hl}));
	});
const spaced = (w: string, k: number) => (k > 0 && !/^[?.,!:;]/.test(w) ? ' ' : '') + w;

// ---------------------------------------------------------------------------
// World layout: one conveyor line the camera travels along (world units).
//   top run (left to right):     shelf with three files -> Extract funnel
//   middle run (right to left):  Transform: cleaning arch, then shaping press
//   bottom run (left to right):  Load: stacking arm -> one table, dashboard on top
// ---------------------------------------------------------------------------

const RUN_Y = [440, 1090, 1740]; // belt surface of the three runs
const BEND_R = (RUN_Y[1] - RUN_Y[0]) / 2;
const BELT = {x0: 1250, right: 1900, left: 400, x1: 1330};
const SEG = [BELT.right - BELT.x0, Math.PI * BEND_R, BELT.right - BELT.left, Math.PI * BEND_R, BELT.x1 - BELT.left];
const BELT_LEN = SEG.reduce((a, b) => a + b, 0);
const BELT_D = `M ${BELT.x0} ${RUN_Y[0]} L ${BELT.right} ${RUN_Y[0]} A ${BEND_R} ${BEND_R} 0 0 1 ${BELT.right} ${RUN_Y[1]} L ${BELT.left} ${RUN_Y[1]} A ${BEND_R} ${BEND_R} 0 0 0 ${BELT.left} ${RUN_Y[2]} L ${BELT.x1} ${RUN_Y[2]}`;

// Point on the belt at distance d from its start, with the outward ("up") normal.
const posAt = (dist: number) => {
	let d = Math.max(0, Math.min(BELT_LEN, dist));
	if (d <= SEG[0]) return {x: BELT.x0 + d, y: RUN_Y[0], nx: 0, ny: -1, dir: 0};
	d -= SEG[0];
	if (d <= SEG[1]) {
		const a = d / BEND_R;
		return {x: BELT.right + BEND_R * Math.sin(a), y: RUN_Y[0] + BEND_R * (1 - Math.cos(a)), nx: Math.sin(a), ny: -Math.cos(a), dir: (a * 180) / Math.PI};
	}
	d -= SEG[1];
	if (d <= SEG[2]) return {x: BELT.right - d, y: RUN_Y[1], nx: 0, ny: -1, dir: 180};
	d -= SEG[2];
	if (d <= SEG[3]) {
		const a = d / BEND_R;
		return {x: BELT.left - BEND_R * Math.sin(a), y: RUN_Y[1] + BEND_R * (1 - Math.cos(a)), nx: -Math.sin(a), ny: -Math.cos(a), dir: 180 - (a * 180) / Math.PI};
	}
	d -= SEG[3];
	return {x: BELT.left + d, y: RUN_Y[2], nx: 0, ny: -1, dir: 0};
};

const FILE = {x0: 60, step: 395, w: 380, top: 80, rowY: 190, rowStep: 70};
const SHELF = {x0: 40, x1: BELT.x0, y: RUN_Y[0]};
const ROW = {w: 460, h: 58, step: 64};
const FUNNEL = {x: 1560, top: -130, neck: 40};
const ARCH = {x: 1380, w: 440, top: 690};
const BIN = {x: 1100, y: 1160, w: 150, h: 130};
const SIDE = {x: 1850, y: 830, w: 400};
const PRESS = {x: 720, w: 560, top: 640};
const ARM = {x: 1410, top: 1400};
const TABLE = {x: 1530, w: 500, top: 1690, head: 64, rowStep: 66, slots: 5};
const DASH = {x: 1520, y: 1320, w: 520, h: 330, base: 1570, barW: 90, maxH: 170};
const BADGE = [{x: FUNNEL.x, y: -50}, {x: ARCH.x, y: ARCH.top}, {x: ARM.x, y: ARM.top}]; // station numbers
const NOTE = {x: 800, y: 1400}; // free space beside the belt: the word ETL, then the rule badge

// Stops along the belt (distance from its start).
const D_FUNNEL = FUNNEL.x - BELT.x0;
const D_ARCH = SEG[0] + SEG[1] + (BELT.right - ARCH.x);
const D_PRESS = SEG[0] + SEG[1] + (BELT.right - PRESS.x);
const D_ARM = BELT_LEN - 180;

// The tray's journey: funnel -> arch -> press -> arm. Every time is keyed to a scene start.
const T = {
	leaveFunnel: S[4] + 130, atArch: S[5] + 30,
	leaveArch: S[5] + 142, atPress: S[6] + 30,
	leavePress: S[6] + 74, atArm: S[7] + 20,
};
const trayD = (f: number) =>
	kf(f, [T.leaveFunnel, T.atArch, T.leaveArch, T.atPress, T.leavePress, T.atArm], [D_FUNNEL, D_ARCH, D_ARCH, D_PRESS, D_PRESS, D_ARM]);
const trayAnchor = (f: number) => posAt(trayD(f));

// ---------------------------------------------------------------------------
// Camera: starts on the whole line, visits the shelf, follows the tray from
// station to station, and pulls back to show the line running.
// ---------------------------------------------------------------------------

const OV = {x: 1132, y: 980, s: 0.42}; // overview: the whole zigzag
type Key = {f: number; x: number; y: number; s: number; e?: Ease};
// Camera keys that track the tray between two stops (the tray's own easing carries the move).
const follow = (f0: number, f1: number, off0: {x: number; y: number; s: number}, off1: {x: number; y: number; s: number}, n = 7): Key[] =>
	Array.from({length: n}, (_, i) => {
		const t = (i + 1) / n;
		const fr = f0 + (f1 - f0) * t;
		const a = trayAnchor(fr);
		return {f: fr, x: a.x + off0.x + (off1.x - off0.x) * t, y: a.y + off0.y + (off1.y - off0.y) * t, s: off0.s + (off1.s - off0.s) * t, e: EASE.linear};
	});
const AT_FUNNEL = {x: 0, y: -210, s: 0.85};
const AT_ARCH = {x: 180, y: -40, s: 0.8};
const AT_PRESS = {x: 40, y: -120, s: 0.9};
const AT_ARM = {x: 285, y: 0, s: 0.8};
const SHELF_VIEW = {x: 645, y: 160, s: 0.8};
const DASH_VIEW = {x: 1800, y: 1710, s: 0.9};
const CAM: Key[] = [
	{f: S[1], ...OV},
	{f: S[1] + 40, ...SHELF_VIEW},
	{f: S[3], ...SHELF_VIEW},
	{f: S[3] + 45, ...OV},
	{f: S[4], ...OV},
	{f: S[4] + 30, x: 1000, y: 200, s: 0.6},
	{f: S[4] + 70, x: 1000, y: 200, s: 0.6},
	{f: S[4] + 115, x: FUNNEL.x, y: RUN_Y[0] + AT_FUNNEL.y, s: AT_FUNNEL.s},
	{f: T.leaveFunnel, x: FUNNEL.x, y: RUN_Y[0] + AT_FUNNEL.y, s: AT_FUNNEL.s, e: EASE.linear},
	...follow(T.leaveFunnel, T.atArch, AT_FUNNEL, AT_ARCH),
	{f: T.leaveArch, x: ARCH.x + AT_ARCH.x, y: RUN_Y[1] + AT_ARCH.y, s: AT_ARCH.s, e: EASE.linear},
	...follow(T.leaveArch, T.atPress, AT_ARCH, AT_PRESS),
	{f: T.leavePress, x: PRESS.x + AT_PRESS.x, y: RUN_Y[1] + AT_PRESS.y, s: AT_PRESS.s, e: EASE.linear},
	...follow(T.leavePress, T.atArm, AT_PRESS, AT_ARM),
	{f: S[8], x: BELT.x1 - 180 + AT_ARM.x, y: RUN_Y[2], s: AT_ARM.s},
	{f: S[8] + 40, ...OV},
	{f: S[9], ...OV},
	{f: S[9] + 40, ...DASH_VIEW},
	{f: S[10], ...DASH_VIEW},
	{f: S[10] + 40, ...OV},
	{f: S[11], ...OV},
	{f: S[11] + 30, x: 1500, y: 1300, s: 0.5},
];
const camera = (f: number) => {
	const fr = CAM.map((k) => k.f);
	const e = CAM.slice(0, -1).map((k) => k.e ?? EASE.inOut);
	return {x: kf(f, fr, CAM.map((k) => k.x), e), y: kf(f, fr, CAM.map((k) => k.y), e), s: kf(f, fr, CAM.map((k) => k.s), e)};
};

// The shelf, the belt that unrolls from its front edge, the rollers and the direction chevrons.
const ROLLERS = RUN_Y.flatMap((y, run) => {
	const [a, b] = run === 0 ? [BELT.x0 + 40, BELT.right - 40] : run === 1 ? [BELT.left + 40, BELT.right - 40] : [BELT.left + 40, BELT.x1 - 40];
	const n = Math.round((b - a) / 115);
	return Array.from({length: n + 1}, (_, i) => ({x: a + ((b - a) * i) / n, y: y + 38}));
});
const BELT_DRAW = [S[3] + 8, S[3] + 38];
const Belt: React.FC<{f: number}> = ({f}) => {
	const draw = enter(f, BELT_DRAW, [0, 1]);
	const rollers = enter(f, [S[3] + 24, S[3] + 44], [0, 1]);
	const chev = enter(f, [S[3] + 40, S[3] + 52], [0, 1]) * kf(f, [S[4] - 10, S[4]], [1, 0], EASE.in);
	const turn = Math.max(0, f - S[3] - 24) * 6;
	return (
		<g>
			<line x1={SHELF.x0} y1={SHELF.y} x2={SHELF.x1} y2={SHELF.y} stroke={C.navy} strokeWidth={14} strokeLinecap="round" />
			{[SHELF.x0 + 60, SHELF.x1 - 60].map((x) => (
				<line key={x} x1={x} y1={SHELF.y + 14} x2={x} y2={SHELF.y + 70} stroke={C.navy} strokeWidth={10} strokeLinecap="round" />
			))}
			<g opacity={rollers}>
				{ROLLERS.map((r, i) => (
					<g key={i} transform={`translate(${r.x} ${r.y}) rotate(${turn})`}>
						<circle r={24} fill={C.purple} />
						<line x1={-14} x2={14} stroke="#fff" strokeWidth={6} strokeLinecap="round" />
					</g>
				))}
			</g>
			<path d={BELT_D} fill="none" stroke={C.navy} strokeWidth={16} strokeLinecap="round" pathLength={1} strokeDasharray="1 1" strokeDashoffset={1 - draw} />
			{/* Tread marks slide along the belt in its one direction. */}
			<path d={BELT_D} fill="none" stroke="#fff" strokeWidth={5} strokeLinecap="round" strokeDasharray="24 130" strokeDashoffset={-f * 8} opacity={draw >= 1 ? 1 : 0} />
			{chev > 0 && Array.from({length: 9}, (_, i) => {
				const p = posAt(((i * BELT_LEN) / 9 + (f - S[3]) * 14) % BELT_LEN);
				return (
					<path key={i} d="M -16 -20 L 8 0 L -16 20" fill="none" stroke={C.violet} strokeWidth={10} strokeLinecap="round" strokeLinejoin="round" opacity={chev}
						transform={`translate(${p.x + p.nx * 60} ${p.y + p.ny * 60}) rotate(${p.dir})`} />
				);
			})}
		</g>
	);
};

// Hook: a dotted violet route from the files to the dashboard, along the line the belt will take.
const HookPath: React.FC<{f: number}> = ({f}) => {
	const d = `M 645 ${SHELF.y - 60} L ${BELT.x0} ${SHELF.y - 60} ${BELT_D.replace('M', 'L')} L ${DASH.x - 30} ${RUN_Y[2]}`;
	const p = enter(f, [S[0] + 40, S[0] + 70], [0, 1]);
	const o = kf(f, [S[1], S[1] + 12], [1, 0], EASE.in);
	if (o <= 0) return null;
	return (
		<g opacity={o}>
			<mask id="hookMask" maskUnits="userSpaceOnUse" x={-200} y={-400} width={2800} height={2800}>
				<path d={d} pathLength={1} fill="none" stroke="#fff" strokeWidth={40} strokeDasharray="1 1" strokeDashoffset={1 - p} />
			</mask>
			<path d={d} mask="url(#hookMask)" fill="none" stroke={C.violet} strokeWidth={14} strokeDasharray="0 34" strokeLinecap="round" />
		</g>
	);
};

// ---------------------------------------------------------------------------
// Rows: every row card on screen comes from content.json and keeps its identity.
// ---------------------------------------------------------------------------

type Kind = 'date' | 'item' | 'amount';
type RowData = {date: string; shown: string; item: string; amount: number | null; order: Kind[]; w: number};
const COLS = content.columns as Kind[];
const ROWS = content.files.flatMap((file, fi) =>
	file.rows.map((r, j) => ({...r, order: file.order as Kind[], w: file.rowWidth, file: fi, j, tilt: [-2, 1.5, 2, -1.5, -2.5][(fi * 2 + j) % 5]})),
);
// The pipeline's rules, written by people: a row identical to an earlier one in its file is a repeat;
// a row without an amount is set aside. Nothing is filled in.
const IS_DUP = ROWS.map((r, i) => ROWS.some((q, k) => k < i && q.file === r.file && q.shown === r.shown && q.item === r.item && q.amount === r.amount));
const IS_FLAG = ROWS.map((r) => r.amount === null);
const CLEAN = ROWS.map((_, i) => i).filter((i) => !IS_DUP[i] && !IS_FLAG[i]);
const NIGHT: RowData[] = content.nightRows.map((r) => ({...r, shown: r.date, order: COLS, w: ROW.w}));
const filePos = (i: number) => ({x: FILE.x0 + ROWS[i].file * FILE.step + FILE.w / 2, y: FILE.rowY + ROWS[i].j * FILE.rowStep});

const ROW_FONT = 30;
const COL_W = [0.44, 0.28, 0.28];
// Cell centers and widths: the file's own order and widths, or the three shared columns once shaped.
const cells = (r: RowData, w: number, cleaned: boolean, shaped: boolean) => {
	const text = (k: Kind) => (k === 'date' ? (cleaned ? r.date : r.shown) : k === 'item' ? r.item : r.amount === null ? '' : String(r.amount));
	if (shaped) {
		let x = -w / 2;
		return COLS.map((k, c) => {
			const cw = COL_W[c] * w;
			x += cw;
			return {kind: k, text: text(k), cx: x - cw / 2, w: cw};
		});
	}
	const widths = r.order.map((k) => Math.max(40, text(k).length * ROW_FONT * 0.58));
	const gap = (w - widths.reduce((a, b) => a + b, 0)) / (widths.length + 1);
	let x = -w / 2;
	return r.order.map((k, c) => {
		x += gap + widths[c];
		return {kind: k, text: text(k), cx: x - widths[c] / 2, w: widths[c]};
	});
};

const RowCard: React.FC<{
	r: RowData; x: number; y: number; w?: number; o?: number; rot?: number; scale?: number;
	cleaned?: boolean; shaped?: number; detail: number; glow?: number; flip?: number;
}> = ({r, x, y, w = r.w, o = 1, rot = 0, scale = 1, cleaned = false, shaped = 0, detail, glow = 0, flip = 1}) => {
	if (o <= 0) return null;
	const isShaped = shaped > 0.5;
	const cs = cells(r, w, cleaned, isShaped);
	return (
		<g transform={`translate(${x} ${y}) rotate(${rot}) scale(${scale})`} opacity={o}>
			<rect x={-w / 2} y={-ROW.h / 2} width={w} height={ROW.h} rx={12} fill={mixColor(mixColor(C.card, C.lavenderTint, shaped), C.lavender, glow * 0.7)}
				stroke={mixColor(C.navy, C.violet, shaped)} strokeWidth={6} filter={glow > 0 ? 'url(#glow)' : undefined} />
			{isShaped && cs.slice(1).map((c) => (
				<line key={c.kind} x1={c.cx - c.w / 2} y1={-ROW.h / 2 + 8} x2={c.cx - c.w / 2} y2={ROW.h / 2 - 8} stroke={C.violet} strokeWidth={4} strokeLinecap="round" />
			))}
			{cs.map((c) =>
				c.text === '' ? (
					<rect key={c.kind} x={c.cx - 26} y={-17} width={52} height={34} rx={8} fill="none" stroke={C.navy} strokeWidth={4} strokeDasharray="8 7" strokeLinecap="round" />
				) : (
					<g key={c.kind} transform={c.kind === 'date' ? `scale(1 ${flip})` : undefined}>
						{/* Pulled back, text would be too small to read: a bar stands in for each value. */}
						<rect x={c.cx - c.w * 0.36} y={-7} width={c.w * 0.72} height={14} rx={7} fill={C.lavender} opacity={1 - detail} />
						<text x={c.cx} y={ROW_FONT * 0.36} fontSize={ROW_FONT} fontWeight={600} textAnchor="middle" fill={C.navy} opacity={detail}>{c.text}</text>
					</g>
				),
			)}
		</g>
	);
};

// The three source files on the shelf. Extract copies them; these originals never change.
const SourceFiles: React.FC<{f: number; detail: number}> = ({f, detail}) => (
	<g>
		{content.files.map((file, i) => {
			const t = [S[0] + 8 + i * 8, S[0] + 32 + i * 8];
			const x = FILE.x0 + i * FILE.step;
			const tag = enter(f, [S[1] + 30 + i * 18, S[1] + 46 + i * 18], [0, 1]) * kf(f, [S[3], S[3] + 12], [1, 0], EASE.in);
			return (
				<g key={i} opacity={enter(f, t, [0, 1])}
					transform={`translate(0 ${enter(f, t, [-260, 0])}) rotate(${enter(f, t, [[-14, 10, -8][i], 0])} ${x + FILE.w / 2} ${SHELF.y})`}>
					<rect x={x} y={FILE.top} width={FILE.w} height={SHELF.y - 10 - FILE.top} rx={20} fill={C.background} stroke={C.navy} strokeWidth={5} filter="url(#soft)" />
					{/* A different look per file: spreadsheet grid, plain text export, notebook rings. */}
					{i === 0 && [1, 2, 3].map((k) => <line key={k} x1={x + k * 95} y1={FILE.top + 70} x2={x + k * 95} y2={SHELF.y - 30} stroke={C.grid} strokeWidth={4} />)}
					{i === 2 && [0, 1, 2, 3, 4, 5].map((k) => <circle key={k} cx={x + 40 + k * 60} cy={FILE.top} r={11} fill={C.background} stroke={C.navy} strokeWidth={5} />)}
					<g opacity={tag} transform={`translate(0 ${(1 - tag) * 24})`}>
						<rect x={x + 20} y={FILE.top + 20} width={150} height={52} rx={26} fill={C.navy} />
						<text x={x + 95} y={FILE.top + 57} fontSize={32} fontWeight={600} textAnchor="middle" fill="#fff" opacity={detail}>{file.name}</text>
					</g>
					{ROWS.map((r, k) => (r.file === i ? <RowCard key={k} r={r} {...filePos(k)} rot={r.tilt} detail={detail} /> : null))}
				</g>
			);
		})}
	</g>
);

// The bakery the example belongs to, shown only while the camera is on the shelf.
const Shopfront: React.FC<{f: number; detail: number}> = ({f, detail}) => {
	const o = enter(f, [S[1] + 10, S[1] + 30], [0, 1]) * kf(f, [S[3], S[3] + 12], [1, 0], EASE.in);
	if (o <= 0) return null;
	return (
		<g opacity={o} transform={`translate(0 ${(1 - o) * 24})`}>
			<rect x={70} y={-90} width={210} height={130} rx={12} fill={C.card} stroke={C.navy} strokeWidth={6} />
			<path d="M 50 -90 L 80 -150 L 270 -150 L 300 -90 Z" fill={C.lavender} stroke={C.navy} strokeWidth={6} strokeLinejoin="round" />
			<rect x={100} y={-55} width={70} height={95} rx={8} fill={C.lavenderTint} stroke={C.navy} strokeWidth={6} />
			<rect x={195} y={-55} width={60} height={50} rx={8} fill={C.lavenderTint} stroke={C.navy} strokeWidth={6} />
			<g opacity={detail}>
				<text x={330} y={-70} fontSize={44} fontWeight={700} fill={C.navy}>{content.bakery.name}</text>
				<text x={330} y={-22} fontSize={32} fontWeight={500} fill={C.muted}>{content.bakery.note}</text>
			</g>
		</g>
	);
};

// Scene 3: the three problems, marked in navy (never red): mismatched dates get dashed outlines,
// the repeated rows a bracket, the missing price a question-mark flag.
const dateCell = (i: number) => {
	const c = cells(ROWS[i], ROWS[i].w, false, false).find((q) => q.kind === 'date')!;
	const p = filePos(i);
	return {x: p.x + c.cx, y: p.y, w: c.w * 0.92 + 14};
};
const QFlag: React.FC<{x: number; y: number; p: number}> = ({x, y, p}) => (
	<g transform={`translate(${x} ${y}) scale(${0.96 + 0.04 * p})`} opacity={p}>
		<line x1={0} y1={0} x2={0} y2={-34} stroke={C.navy} strokeWidth={6} strokeLinecap="round" />
		<circle cx={0} cy={-58} r={28} fill={C.navy} />
		<text x={0} y={-45} fontSize={38} fontWeight={700} textAnchor="middle" fill="#fff">?</text>
	</g>
);
const Problems: React.FC<{f: number; detail: number}> = ({f, detail}) => {
	const out = kf(f, [S[3], S[3] + 10], [1, 0], EASE.in);
	if (f < S[2] || out <= 0) return null;
	const dates = enter(f, [S[2] + 6, S[2] + 20], [0, 1]);
	const same = enter(f, [S[2] + 40, S[2] + 54], [0, 1]);
	const miss = enter(f, [S[2] + 74, S[2] + 88], [0, 1]);
	const firstOther = ROWS.findIndex((r) => r.shown !== ROWS[0].shown);
	const dup = IS_DUP.indexOf(true);
	const flagged = IS_FLAG.indexOf(true);
	const blank = cells(ROWS[flagged], ROWS[flagged].w, false, false).find((q) => q.kind === 'amount')!;
	const a = filePos(dup - 1);
	const b = filePos(dup);
	return (
		<g opacity={out}>
			{[0, firstOther].map((i) => {
				const d = dateCell(i);
				return <rect key={i} x={d.x - d.w / 2} y={d.y - 40} width={d.w} height={80} rx={14} fill="none" stroke={C.navy} strokeWidth={6}
					strokeDasharray="16 12" strokeLinecap="round" opacity={dates} />;
			})}
			<g opacity={dates} transform={`translate(${FILE.x0 + FILE.w + (FILE.step - FILE.w) / 2} ${FILE.top - 30}) scale(${0.96 + 0.04 * dates})`}>
				<circle r={30} fill={C.violet} />
				<text y={14} fontSize={40} fontWeight={700} textAnchor="middle" fill="#fff">≠</text>
			</g>
			<g opacity={same}>
				<path d={`M ${a.x + 166} ${a.y - 30} L ${a.x + 182} ${a.y - 30} L ${a.x + 182} ${b.y + 30} L ${a.x + 166} ${b.y + 30}`} fill="none" stroke={C.navy} strokeWidth={7}
					strokeLinecap="round" strokeLinejoin="round" />
				<g transform={`translate(0 ${(1 - same) * 24})`} opacity={detail}>
					<rect x={a.x - 150} y={b.y + 52} width={300} height={52} rx={26} fill={C.navy} />
					<text x={a.x} y={b.y + 88} fontSize={30} fontWeight={600} textAnchor="middle" fill="#fff">{content.labels.sameSale}</text>
				</g>
			</g>
			<QFlag x={filePos(flagged).x + blank.cx} y={filePos(flagged).y - 20} p={miss} />
		</g>
	);
};

// The three stations and the table, which rise onto the belt in scene 4.
const stationIn = (f: number, i: number) => enter(f, [S[3] + 50 + i * 12, S[3] + 70 + i * 12], [0, 1]);
const Rise: React.FC<{p: number; children: React.ReactNode}> = ({p, children}) => (p <= 0 ? null : <g opacity={p} transform={`translate(0 ${(1 - p) * 24})`}>{children}</g>);
const PRESS_T = [S[6] + 32, S[6] + 50, S[6] + 54, S[6] + 72];
const Stations: React.FC<{f: number; detail: number}> = ({f, detail}) => {
	const paths = enter(f, [S[4] + 12, S[4] + 40], [0, 1]) * kf(f, [S[5], S[5] + 12], [1, 0], EASE.in);
	const check = enter(f, [S[5] + 118, S[5] + 132], [0, 1]) * kf(f, [T.leaveArch, T.leaveArch + 12], [1, 0], EASE.in);
	const colLabels = enter(f, [S[6] + 8, S[6] + 24], [0, 1]) * kf(f, [T.leavePress + 10, T.leavePress + 22], [1, 0], EASE.in);
	const plate = kf(f, PRESS_T, [PRESS.top + 90, RUN_Y[1] - 248, RUN_Y[1] - 248, PRESS.top + 90]);
	const ax = ARCH.x, hw = ARCH.w / 2, px = PRESS.x, pw = PRESS.w / 2;
	return (
		<g>
			{/* 1 Extract: a collecting funnel, fed by one violet path per file. */}
			{content.files.map((_, i) => {
				const x = FILE.x0 + i * FILE.step + FILE.w / 2;
				return <path key={i} d={`M ${x} ${FILE.top} Q ${(x + FUNNEL.x) / 2} -330 ${FUNNEL.x} ${FUNNEL.top}`} fill="none" stroke={C.violet} strokeWidth={9} strokeLinecap="round"
					pathLength={1} strokeDasharray="1 1" strokeDashoffset={1 - enter(f, [S[4] + 12, S[4] + 40], [0, 1])} opacity={paths} />;
			})}
			<Rise p={stationIn(f, 0)}>
				<path d={`M ${FUNNEL.x - 190} ${FUNNEL.top} L ${FUNNEL.x + 190} ${FUNNEL.top} L ${FUNNEL.x + 70} ${FUNNEL.neck} L ${FUNNEL.x + 70} ${FUNNEL.neck + 50} L ${FUNNEL.x - 70} ${FUNNEL.neck + 50} L ${FUNNEL.x - 70} ${FUNNEL.neck} Z`}
					fill={C.lavenderTint} stroke={C.navy} strokeWidth={10} strokeLinejoin="round" />
			</Rise>
			{/* 2 Transform: a cleaning arch with a bin and a side tray, then a shaping press. */}
			<Rise p={stationIn(f, 1)}>
				<path d={`M ${ax - hw} ${RUN_Y[1] - 12} L ${ax - hw} ${ARCH.top + 130} Q ${ax - hw} ${ARCH.top} ${ax - hw + 130} ${ARCH.top} L ${ax + hw - 130} ${ARCH.top} Q ${ax + hw} ${ARCH.top} ${ax + hw} ${ARCH.top + 130} L ${ax + hw} ${RUN_Y[1] - 12}`}
					fill={C.lavenderTint} fillOpacity={0.6} stroke={C.navy} strokeWidth={12} strokeLinecap="round" />
				<path d={`M ${BIN.x - BIN.w / 2} ${BIN.y} L ${BIN.x - BIN.w / 2 + 14} ${BIN.y + BIN.h} L ${BIN.x + BIN.w / 2 - 14} ${BIN.y + BIN.h} L ${BIN.x + BIN.w / 2} ${BIN.y}`}
					fill={C.card} stroke={C.navy} strokeWidth={10} strokeLinecap="round" strokeLinejoin="round" />
				<line x1={SIDE.x - SIDE.w / 2} y1={SIDE.y + 36} x2={SIDE.x + SIDE.w / 2} y2={SIDE.y + 36} stroke={C.navy} strokeWidth={10} strokeLinecap="round" />
				<text x={SIDE.x} y={SIDE.y + 86} fontSize={32} fontWeight={600} textAnchor="middle" fill={C.navy} opacity={check * detail}>{content.labels.check}</text>
				{[-pw, pw].map((d) => <line key={d} x1={px + d} y1={PRESS.top} x2={px + d} y2={RUN_Y[1] - 12} stroke={C.navy} strokeWidth={12} strokeLinecap="round" />)}
				<line x1={px} y1={PRESS.top + 60} x2={px} y2={plate} stroke={C.navy} strokeWidth={14} />
				<rect x={px - ROW.w / 2 - 20} y={plate} width={ROW.w + 40} height={40} rx={10} fill={C.navy} />
				<rect x={px - pw - 10} y={PRESS.top} width={PRESS.w + 20} height={70} rx={16} fill={C.navy} />
				{COLS.map((k, c) => (
					<text key={k} x={px - ROW.w / 2 + (COL_W.slice(0, c).reduce((s, v) => s + v, 0) + COL_W[c] / 2) * ROW.w} y={PRESS.top + 46} fontSize={28} fontWeight={600}
						textAnchor="middle" fill="#fff" opacity={colLabels * detail}>{k}</text>
				))}
			</Rise>
			{/* 3 Load: the stacking arm's post (the arm itself follows the rows) and the one table. */}
			<Rise p={stationIn(f, 2)}>
				<line x1={ARM.x} y1={ARM.top} x2={ARM.x} y2={RUN_Y[2] + 62} stroke={C.navy} strokeWidth={14} strokeLinecap="round" />
			</Rise>
			<Rise p={stationIn(f, 3)}>
				<rect x={TABLE.x} y={TABLE.top} width={TABLE.w} height={TABLE.head + TABLE.slots * TABLE.rowStep + 16} rx={20} fill={C.card} stroke={C.navy} strokeWidth={10} filter="url(#soft)" />
				<path d={`M ${TABLE.x} ${TABLE.top + TABLE.head} L ${TABLE.x} ${TABLE.top + 20} Q ${TABLE.x} ${TABLE.top} ${TABLE.x + 20} ${TABLE.top} L ${TABLE.x + TABLE.w - 20} ${TABLE.top} Q ${TABLE.x + TABLE.w} ${TABLE.top} ${TABLE.x + TABLE.w} ${TABLE.top + 20} L ${TABLE.x + TABLE.w} ${TABLE.top + TABLE.head} Z`} fill={C.navy} />
				{COLS.map((k, c) => (
					<text key={k} x={TABLE.x + 20 + (COL_W.slice(0, c).reduce((s, v) => s + v, 0) + COL_W[c] / 2) * ROW.w} y={TABLE.top + 43} fontSize={30} fontWeight={600}
						textAnchor="middle" fill="#fff" opacity={detail}>{k}</text>
				))}
			</Rise>
		</g>
	);
};

// ---------------------------------------------------------------------------
// The tray's rows: copied out of the files, cleaned under the arch, shaped by the
// press, and stacked into the table. One function gives a row's state at any frame.
// ---------------------------------------------------------------------------

const slotY = (slot: number) => -51 - slot * ROW.step; // above the tray's anchor on the belt
const tableSlot = (p: number) => ({x: TABLE.x + TABLE.w / 2, y: TABLE.top + TABLE.head + 12 + ROW.h / 2 + p * TABLE.rowStep});
const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
const FLY = (i: number) => S[4] + 40 + i * 8; // copy leaves its file
const CROSS_T = [S[5] + 58, S[5] + 70];
const TIP_T = [S[5] + 74, S[5] + 98];
const FLAG_T = [S[5] + 84, S[5] + 96];
const ASIDE_T = [S[5] + 100, S[5] + 122];
const SETTLE_T = [S[5] + 102, S[5] + 120];
const FLIP_T = [S[5] + 120, S[5] + 129, S[5] + 138];
const SHAPE_T = [PRESS_T[1] - 6, PRESS_T[1] + 12];
const PLACE = (p: number) => S[7] + 24 + p * 36; // arm lifts the p-th row (top of the stack first)
const PLACE_F = 18;
const PULSE = (p: number) => S[9] + 56 + p * 24; // table row pulses, its bar grows

const rowState = (i: number, f: number) => {
	const r = ROWS[i];
	const a = trayAnchor(f);
	const c = CLEAN.indexOf(i);
	const fly0 = FLY(i);
	const from = filePos(i);
	// file -> over the funnel (curved) -> down onto the tray
	const t = kf(f, [fly0, fly0 + 36], [0, 1]);
	const mx = (from.x + FUNNEL.x) / 2;
	let x = (1 - t) * (1 - t) * from.x + 2 * t * (1 - t) * mx + t * t * FUNNEL.x;
	let y = (1 - t) * (1 - t) * from.y + 2 * t * (1 - t) * -330 + t * t * (FUNNEL.top - 20);
	let scale = lerp(1, 0.5, t);
	let rot = r.tilt * (1 - t);
	let o = enter(f, [fly0, fly0 + 12], [0, 1]);
	const slot = c < 0 ? i : lerp(i, c, kf(f, SETTLE_T, [0, 1]));
	if (f > fly0 + 36) {
		const d = kf(f, [fly0 + 36, fly0 + 54], [0, 1]);
		y = lerp(FUNNEL.top - 20, a.y + slotY(slot), d);
		x = a.x;
		scale = lerp(0.5, 1, d);
	}
	let shaped = 0;
	let w = r.w;
	if (IS_DUP[i] && f > TIP_T[0]) {
		// The repeated row tips off the belt into the bin.
		const d = kf(f, TIP_T, [0, 1], EASE.in);
		x = lerp(ARCH.x, BIN.x, d);
		y = lerp(RUN_Y[1] + slotY(i), BIN.y + 30, d);
		rot = -72 * d;
		scale = lerp(1, 0.42, d);
	} else if (IS_FLAG[i] && f > ASIDE_T[0]) {
		// The row with no price moves to the side tray for a person to check.
		const d = kf(f, ASIDE_T, [0, 1]);
		x = lerp(ARCH.x, SIDE.x, d);
		y = lerp(RUN_Y[1] + slotY(i), SIDE.y, d);
	} else if (c >= 0) {
		shaped = kf(f, SHAPE_T, [0, 1]);
		// The unified date is longer, so the card widens a little; the press then makes every card the same.
		w = lerp(lerp(r.w, 350, kf(f, [FLIP_T[0], FLIP_T[2]], [0, 1])), ROW.w, shaped);
		const p = CLEAN.length - 1 - c;
		const d = kf(f, [PLACE(p), PLACE(p) + PLACE_F], [0, 1]);
		const to = tableSlot(p);
		x = lerp(x, to.x, d);
		y = lerp(y, to.y, d);
	}
	return {x, y, scale, rot, o, shaped, w, cleaned: c >= 0 && f >= FLIP_T[1], flip: c >= 0 ? kf(f, FLIP_T, [1, 0, 1]) : 1,
		glow: c < 0 ? 0 : kf(f, [PULSE(CLEAN.length - 1 - c), PULSE(CLEAN.length - 1 - c) + 8, PULSE(CLEAN.length - 1 - c) + 16], [0, 1, 0])};
};

// Night run (scene 11): a fresh tray rides the whole line and its rows join the table.
const NIGHT_T = [S[10] + 50, S[10] + 110];
const NIGHT_PLACE = (n: number) => S[10] + 112 + n * 8;
const NIGHT_F = 18;
const nightState = (n: number, f: number) => {
	const d = kf(f, NIGHT_T, [D_FUNNEL, D_ARM]);
	const a = posAt(d);
	const t = kf(f, [NIGHT_PLACE(n), NIGHT_PLACE(n) + NIGHT_F], [0, 1]);
	const to = tableSlot(CLEAN.length + n);
	return {x: lerp(a.x, to.x, t), y: lerp(a.y + slotY(n), to.y, t), o: enter(f, [S[10] + 38, S[10] + 52], [0, 1]), shaped: clamp01((d - D_PRESS) / 80)};
};
const stored = (f: number) => CLEAN.filter((_, p) => f >= PLACE(p) + PLACE_F).length + NIGHT.filter((_, n) => f >= NIGHT_PLACE(n) + NIGHT_F).length;

const Slab: React.FC<{x: number; y: number; o: number}> = ({x, y, o}) => (
	<rect x={x - ROW.w / 2 - 15} y={y - 22} width={ROW.w + 30} height={14} rx={7} fill={C.navy} opacity={o} />
);

const TrayRows: React.FC<{f: number; detail: number}> = ({f, detail}) => {
	const a = trayAnchor(f);
	const lastPlaced = PLACE(CLEAN.length - 1) + PLACE_F;
	const slab = enter(f, [S[4] + 60, S[4] + 78], [0, 1]) * kf(f, [lastPlaced + 2, lastPlaced + 14], [1, 0], EASE.in);
	const na = posAt(kf(f, NIGHT_T, [D_FUNNEL, D_ARM]));
	const nSlab = enter(f, [S[10] + 38, S[10] + 52], [0, 1]) * kf(f, [NIGHT_PLACE(NIGHT.length - 1) + 18, NIGHT_PLACE(NIGHT.length - 1) + 30], [1, 0], EASE.in);
	// The arm's gripper travels with the row it is stacking.
	const rest = {x: ARM.x - 150, y: ARM.top + 130};
	const gf = [PLACE(0) - 12, ...CLEAN.flatMap((_, p) => [PLACE(p), PLACE(p) + PLACE_F]), lastPlaced + 14];
	const gp = [rest, ...CLEAN.flatMap((_, p) => [{x: BELT.x1 - 180, y: RUN_Y[2] + slotY(CLEAN.length - 1 - p)}, tableSlot(p)]), rest];
	const grip = {x: kf(f, gf, gp.map((q, k) => q.x - (k > 0 && k < gp.length - 1 ? ROW.w / 2 : 0))), y: kf(f, gf, gp.map((q) => q.y))};
	const cross = enter(f, CROSS_T, [0, 1]);
	const flag = enter(f, FLAG_T, [0, 1]);
	return (
		<g>
			<Slab x={a.x} y={a.y} o={slab} />
			<Slab x={na.x} y={na.y} o={nSlab} />
			{ROWS.map((r, i) => {
				const s = rowState(i, f);
				const blank = cells(r, s.w, s.cleaned, false).find((q) => q.kind === 'amount')!;
				return (
					<g key={i}>
						<RowCard r={r} {...s} detail={detail} />
						{IS_DUP[i] && cross > 0 && (
							<g transform={`translate(${s.x} ${s.y}) rotate(${s.rot}) scale(${s.scale})`}>
								{[1, -1].map((k) => (
									<line key={k} x1={-34} y1={-34 * k} x2={-34 + 68 * cross} y2={-34 * k + 68 * k * cross} stroke={C.navy} strokeWidth={12} strokeLinecap="round" />
								))}
							</g>
						)}
						{IS_FLAG[i] && <QFlag x={s.x + blank.cx} y={s.y - 20} p={flag} />}
					</g>
				);
			})}
			{NIGHT.map((r, n) => <RowCard key={n} r={r} {...nightState(n, f)} cleaned detail={detail} />)}
			{stationIn(f, 2) > 0 && (
				<g opacity={stationIn(f, 2)}>
					<line x1={ARM.x} y1={ARM.top} x2={grip.x} y2={grip.y} stroke={C.navy} strokeWidth={12} strokeLinecap="round" />
					<circle cx={grip.x} cy={grip.y} r={16} fill={C.violet} stroke={C.navy} strokeWidth={6} />
				</g>
			)}
		</g>
	);
};

// Dashboard: one bar per item, built only from the rows stored in the table.
const ITEMS = [...new Set([...CLEAN.map((i) => ROWS[i].item), ...NIGHT.map((r) => r.item)])];
const itemTotal = (item: string, cleanW: (p: number) => number, nightW: (n: number) => number) =>
	CLEAN.reduce((s, i, c) => s + (ROWS[i].item === item ? (ROWS[i].amount ?? 0) * cleanW(CLEAN.length - 1 - c) : 0), 0) +
	NIGHT.reduce((s, r, n) => s + (r.item === item ? (r.amount ?? 0) * nightW(n) : 0), 0);
const itemSum = (cleanW: (p: number) => number, nightW: (n: number) => number) => ITEMS.reduce((s, it) => s + itemTotal(it, cleanW, nightW), 0);
const BAR_MAX = Math.max(...ITEMS.map((it) => itemTotal(it, () => 1, () => 1)));
const Dashboard: React.FC<{f: number; detail: number}> = ({f, detail}) => {
	const hook = f < S[2];
	const o = hook
		? enter(f, [S[0] + 56, S[0] + 76], [0, 1]) * kf(f, [S[1], S[1] + 14], [1, 0], EASE.in)
		: enter(f, [S[9] + 30, S[9] + 50], [0, 1]);
	if (o <= 0) return null;
	const cleanT = (p: number) => (hook ? [S[0] + 74 + p * 8, S[0] + 98 + p * 8] : [PULSE(p) + 4, PULSE(p) + 28]);
	const nightT = (n: number) => [S[10] + 140 + n * 6, S[10] + 164 + n * 6];
	// New bars enter (ease-out); bars already standing grow taller (ease-in-out); the total counts steadily (linear).
	const cleanW = (p: number) => enter(f, cleanT(p), [0, 1]);
	const nightW = (n: number) => (hook ? 0 : kf(f, nightT(n), [0, 1]));
	const total = itemSum((p) => kf(f, cleanT(p), [0, 1], EASE.linear), (n) => (hook ? 0 : kf(f, nightT(n), [0, 1], EASE.linear)));
	const values = ITEMS.map((it) => itemTotal(it, cleanW, nightW));
	const link = hook ? 0 : enter(f, [S[9] + 46, S[9] + 60], [0, 1]);
	const cx = DASH.x + DASH.w / 2;
	return (
		<g>
			<line x1={cx} y1={TABLE.top} x2={cx} y2={TABLE.top - (TABLE.top - DASH.y - DASH.h) * link} stroke={C.violet} strokeWidth={10} strokeLinecap="round" opacity={link > 0 ? 1 : 0} />
			<g opacity={o} transform={`translate(0 ${hook ? 0 : (1 - o) * 24})`}>
				<rect x={DASH.x} y={DASH.y} width={DASH.w} height={DASH.h} rx={20} fill={C.card} stroke={C.navy} strokeWidth={10} filter="url(#glow)" />
				<line x1={DASH.x + 50} y1={DASH.base} x2={DASH.x + DASH.w - 50} y2={DASH.base} stroke={C.navy} strokeWidth={6} strokeLinecap="round" />
				{ITEMS.map((it, k) => {
					const x = cx + (k - (ITEMS.length - 1) / 2) * 140;
					const h = (values[k] / BAR_MAX) * DASH.maxH;
					return (
						<g key={it}>
							{h > 1 && <rect x={x - DASH.barW / 2} y={DASH.base - h} width={DASH.barW} height={h} rx={8} fill={C.purple} stroke={C.navy} strokeWidth={5} />}
							<text x={x} y={DASH.base + 44} fontSize={30} fontWeight={600} textAnchor="middle" fill={C.navy} opacity={detail}>{it}</text>
						</g>
					);
				})}
				<text x={DASH.x + 28} y={DASH.y + 50} fontSize={32} fontWeight={700} fill={C.navy} opacity={detail}>
					{content.labels.total} {Math.round(total)}
				</text>
			</g>
		</g>
	);
};

// Station numbers; in the recap a violet letter lifts out of each and the three lock into "ETL".
const LETTER_T = (i: number) => S[8] + 20 + i * 38;
const GATHER_T = [S[8] + 126, S[8] + 150];
const Badges: React.FC<{f: number}> = ({f}) => {
	const word = kf(f, [S[9], S[9] + 10], [1, 0], EASE.in);
	const count = stored(f);
	return (
		<g>
			{BADGE.map((b, i) => {
				const pulse = kf(f, [LETTER_T(i), LETTER_T(i) + 8, LETTER_T(i) + 16], [0, 1, 0]);
				const up = enter(f, [LETTER_T(i), LETTER_T(i) + 18], [0, 1]);
				const g = kf(f, GATHER_T, [0, 1]);
				return (
					<g key={i}>
						<Rise p={stationIn(f, i)}>
							<circle cx={b.x} cy={b.y} r={70 + pulse * 8} fill={C.violet} filter={pulse > 0 ? 'url(#glow)' : undefined} />
							<text x={b.x} y={b.y + 30} fontSize={84} fontWeight={700} textAnchor="middle" fill="#fff">{i + 1}</text>
						</Rise>
						<text x={lerp(b.x + 200, NOTE.x + (i - 1) * 150, g)} y={lerp(b.y + 60 - up * 24, NOTE.y + 70, g)} fontSize={lerp(150, 210, g)} fontWeight={700}
							textAnchor="middle" fill={C.violet} opacity={up * word}>{content.labels.etl[i]}</text>
					</g>
				);
			})}
			{count > 0 && (
				<g>
					<circle cx={TABLE.x + TABLE.w - 70} cy={TABLE.top + TABLE.head + TABLE.slots * TABLE.rowStep + 16} r={50} fill={C.violet} stroke={C.card} strokeWidth={8} />
					<text x={TABLE.x + TABLE.w - 70} y={TABLE.top + TABLE.head + TABLE.slots * TABLE.rowStep + 35} fontSize={54} fontWeight={700} textAnchor="middle" fill="#fff">{count}</text>
				</g>
			)}
		</g>
	);
};

// Scene 11: night falls on the clock, a new file lands on the shelf, and the rule badge appears.
const Night: React.FC<{f: number}> = ({f}) => {
	if (f < S[10]) return null;
	const clock = enter(f, [S[10] + 4, S[10] + 22], [0, 1]);
	const night = kf(f, [S[10] + 18, S[10] + 36], [0, 1]);
	const t = [S[10] + 22, S[10] + 46];
	const rule = enter(f, [S[10] + 56, S[10] + 76], [0, 1]);
	const ink = mixColor(C.navy, '#ffffff', night);
	return (
		<g>
			<g opacity={clock} transform={`translate(700 ${-50 + (1 - clock) * 24})`}>
				<circle r={84} fill={mixColor(C.card, C.navy, night)} stroke={C.navy} strokeWidth={10} />
				<line x1={0} y1={0} x2={0} y2={-52} stroke={ink} strokeWidth={10} strokeLinecap="round" transform={`rotate(${night * 360})`} />
				<line x1={0} y1={0} x2={34} y2={0} stroke={ink} strokeWidth={10} strokeLinecap="round" transform={`rotate(${night * 180})`} />
			</g>
			<g opacity={enter(f, t, [0, 1])} transform={`translate(0 ${enter(f, t, [-260, 0])}) rotate(${enter(f, t, [10, 0])} 1050 ${SHELF.y})`}>
				<rect x={900} y={170} width={300} height={260} rx={20} fill={C.lavenderTint} stroke={C.violet} strokeWidth={12} />
				{[0, 1].map((k) => <rect key={k} x={940} y={230 + k * 80} width={220 - k * 50} height={26} rx={13} fill={C.violet} />)}
			</g>
			<g opacity={rule} transform={`translate(0 ${(1 - rule) * 24})`}>
				<rect x={NOTE.x - 400} y={NOTE.y - 62} width={800} height={124} rx={20} fill={C.background} stroke={C.violet} strokeWidth={10} filter="url(#soft)" />
				<text x={NOTE.x} y={NOTE.y + 21} fontSize={60} fontWeight={600} textAnchor="middle" fill={C.navy}>{content.labels.rule}</text>
			</g>
		</g>
	);
};

// WORLD-PARTS

const World: React.FC<{f: number; detail: number}> = ({f, detail}) => (
	<g>
		<HookPath f={f} />
		<Belt f={f} />
		<Stations f={f} detail={detail} />
		<Shopfront f={f} detail={detail} />
		<SourceFiles f={f} detail={detail} />
		<Problems f={f} detail={detail} />
		<Dashboard f={f} detail={detail} />
		<TrayRows f={f} detail={detail} />
		<Badges f={f} />
		<Night f={f} />
	</g>
);

// WORLD-END

// Headline: left-aligned, masked reveal line by line, *words* in brand violet.
const Headline: React.FC<{f: number}> = ({f}) => (
	<>
		{content.scenes.map((sc, i) => {
			if (!sc.headline) return null;
			const a = S[i];
			const b = sceneEnd(i);
			const out = kf(f, [b - 8, b], [1, 0], EASE.in);
			if (f < a || out <= 0) return null;
			return (
				<g key={i} opacity={out}>
					{sc.headline.split('\n').map((line, li) => {
						const y = HEADLINE_Y + li * 72;
						const rise = enter(f, [a + li * 4, a + 18 + li * 4], [74, 0]);
						return (
							<g key={li}>
								<clipPath id={`hl-${i}-${li}`}>
									<rect x={0} y={y - 62} width={1080} height={80} />
								</clipPath>
								<text x={SAFE.left} y={y + rise} clipPath={`url(#hl-${i}-${li})`} fontSize={58} fontWeight={700} fill={C.navy}>
									{parseMarked(line).map(({w, hl}, k) => (
										<tspan key={k} fill={hl ? C.violet : C.navy}>{spaced(w, k)}</tspan>
									))}
								</text>
							</g>
						);
					})}
				</g>
			);
		})}
	</>
);

// Subtitles: navy bar in the lower safe area, word-group reveal synced to the voiceover.
const Subtitles: React.FC<{f: number}> = ({f}) => (
	<>
		{content.scenes.map((sc, i) => {
			const start = sc.voStart * FPS;
			const dur = ((voTiming as number[])[i] ?? 3) * FPS;
			const end = Math.min(sceneEnd(i) - 2, start + dur + 18);
			const o = kf(f, [start - 4, start + 4, end - 6, end], [0, 1, 1, 0]);
			if (o <= 0) return null;
			const words = parseMarked(sc.voiceover);
			// Long lines split in two so no line passes seven words or the bar's width.
			const perLine = words.length > 7 || sc.voiceover.length > 40 ? Math.ceil(words.length / 2) : words.length;
			const lines = [words.slice(0, perLine), words.slice(perLine)].filter((l) => l.length);
			const h = 34 + lines.length * 54;
			let n = 0;
			return (
				<g key={i} opacity={o}>
					<rect x={SAFE.left} y={SUB_BOTTOM - h} width={SAFE.right - SAFE.left} height={h} rx={20} fill={C.navy} fillOpacity={0.88} />
					{lines.map((line, li) => (
						<text key={li} x={540} y={SUB_BOTTOM - h + 56 + li * 54} fontSize={40} fontWeight={600} textAnchor="middle">
							{line.map(({w, hl}, k) => {
								// Words reveal in groups of three, paced across the spoken line.
								const group = Math.floor(n++ / 3);
								const at = start + (group * 3 * dur) / words.length;
								return (
									<tspan key={k} fill={hl ? C.lavender : '#fff'} fillOpacity={enter(f, [at, at + 8], [0.25, 1])}>
										{spaced(w, k)}
									</tspan>
								);
							})}
						</text>
					))}
				</g>
			);
		})}
	</>
);

// Outro: the DataEntropy logo (four gradient bars above the wordmark, violet "E"),
// then the tagline and one CTA.
// Guideline motion: bars grow left to right, wordmark reveals after, soft violet glow.
const LOGO = {
	barW: 66,
	gap: 22,
	heights: [96, 156, 212, 276], // proportions of the logo image
	base: 700, // bar baseline (screen y)
	wordY: 832, // wordmark baseline
	wordSize: 104,
};
const Outro: React.FC<{f: number}> = ({f}) => {
	const a = S[S.length - 1];
	if (f < a) return null;
	const {barW, gap, heights, base} = LOGO;
	const symbolW = heights.length * barW + (heights.length - 1) * gap;
	const left = 540 - symbolW / 2;
	const top = base - heights[heights.length - 1];
	const word = enter(f, [a + 38, a + 58], [0, 1]);
	const glow = kf(f, [a + 52, a + 61, a + 70], [0, 1, 0.35]);
	const tag = enter(f, [a + 52, a + 68], [0, 1]);
	const cta = enter(f, [a + 62, a + 80], [0, 1]);
	const arrow = kf(f, [a + 76, a + 94], [0, 10], EASE.inOut);
	return (
		<g>
			<linearGradient id="logoBars" gradientUnits="userSpaceOnUse" x1={left} y1={top} x2={left + symbolW} y2={base}>
				<stop offset="0" stopColor={C.lavender} />
				<stop offset="0.55" stopColor={C.purple} />
				<stop offset="1" stopColor={C.violet} />
			</linearGradient>
			<g filter={glow > 0.05 ? 'url(#glow)' : undefined}>
				{heights.map((bh, k) => {
					const g = enter(f, [a + 8 + k * 7, a + 26 + k * 7], [0, 1]);
					const h = Math.max(barW * g, bh * g); // grows from a rounded stub
					return <rect key={k} x={left + k * (barW + gap)} y={base - h} width={barW} height={h} rx={barW / 2} fill="url(#logoBars)" opacity={g > 0 ? 1 : 0} />;
				})}
			</g>
			<clipPath id="wordmark">
				<rect x={540 - 400} y={LOGO.wordY - 110} width={800 * word} height={150} />
			</clipPath>
			<text x={540} y={LOGO.wordY} clipPath="url(#wordmark)" fontFamily={LOGO_FONT} fontSize={LOGO.wordSize} fontWeight={700}
				textAnchor="middle" fill={C.navy} letterSpacing={-1}>
				Data<tspan fill={C.purple}>E</tspan>ntropy
			</text>
			<text x={540} y={935 + (1 - tag) * 24} fontSize={34} fontWeight={500} textAnchor="middle" fill={C.muted} opacity={tag}>{content.brand.tagline}</text>
			<g opacity={cta} transform={`translate(0 ${(1 - cta) * 24})`}>
				<rect x={260} y={1000} width={560} height={100} rx={20} fill={C.violet} filter="url(#soft)" />
				<text x={520} y={1063} fontSize={38} fontWeight={600} textAnchor="middle" fill="#fff">{content.brand.cta}</text>
				<text x={745 + arrow} y={1063} fontSize={38} fontWeight={600} textAnchor="middle" fill="#fff">→</text>
			</g>
		</g>
	);
};

// ---------------------------------------------------------------------------

export const EtlPipelineVideo: React.FC = () => {
	const f = useCurrentFrame();
	const cam = camera(f);
	const worldO = kf(f, [S[11], S[11] + 18], [1, 0], EASE.in);

	return (
		<AbsoluteFill style={{backgroundColor: C.background, fontFamily: FONT}}>
			<svg width={1080} height={1920} viewBox="0 0 1080 1920" style={{fontFamily: FONT}}>
				<defs>
					<filter id="soft" x="-30%" y="-30%" width="160%" height="170%">
						<feDropShadow dx="0" dy="10" stdDeviation="14" floodColor={C.violet} floodOpacity="0.1" />
					</filter>
					<filter id="glow" x="-50%" y="-50%" width="200%" height="200%">
						<feDropShadow dx="0" dy="0" stdDeviation="12" floodColor={C.violet} floodOpacity="0.35" />
					</filter>
					<pattern id="dots" width={48} height={48} patternUnits="userSpaceOnUse">
						<circle cx={24} cy={24} r={2} fill={C.grid} />
					</pattern>
					<linearGradient id="worldFade" x1="0" y1="0" x2="0" y2="1920" gradientUnits="userSpaceOnUse">
						<stop offset={340 / 1920} stopColor="#fff" stopOpacity={0} />
						<stop offset={400 / 1920} stopColor="#fff" />
						<stop offset={1330 / 1920} stopColor="#fff" />
						<stop offset={1395 / 1920} stopColor="#fff" stopOpacity={0} />
					</linearGradient>
					<mask id="worldMask" maskUnits="userSpaceOnUse" x={0} y={0} width={1080} height={1920}>
						<rect width={1080} height={1920} fill="url(#worldFade)" />
					</mask>
					<radialGradient id="lavGlow" cx="0.85" cy="0.1" r="0.7">
						<stop offset="0" stopColor={C.lavender} stopOpacity={0.35} />
						<stop offset="1" stopColor={C.lavender} stopOpacity={0} />
					</radialGradient>
				</defs>
				<rect width={1080} height={1920} fill="url(#lavGlow)" />
				<g mask="url(#worldMask)">
					<g opacity={worldO} transform={`translate(${540 - cam.x * cam.s} ${CONTENT_CY - cam.y * cam.s}) scale(${cam.s})`}>
						<rect x={-1500} y={-1500} width={5200} height={5200} fill="url(#dots)" />
						<World f={f} detail={clamp01((cam.s - 0.68) / 0.1)} />
					</g>
				</g>
				<Outro f={f} />
				<Headline f={f} />
				<Subtitles f={f} />
			</svg>
			{content.scenes.map((sc, i) => (
				<Sequence key={i} from={Math.round(sc.voStart * FPS)}>
					<Audio src={staticFile(`vo/scene-${i + 1}.wav`)} />
				</Sequence>
			))}
			<Audio src={staticFile('music.wav')} />
		</AbsoluteFill>
	);
};
